const incoming = $json.body || $json;
let body = incoming;

// Mobile-safe requests arrive as a simple form post containing one JSON payload field.
// JSON requests remain supported for backward compatibility and direct API testing.
if (typeof incoming.payload === 'string') {
  try {
    body = JSON.parse(incoming.payload);
  } catch (error) {
    throw new Error('Invalid JSON in form payload.');
  }
}

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Request body must be a JSON object.');
}

const action = String(body.action || '').trim();
const now = new Date().toISOString();

if (!action) {
  throw new Error('Missing action. See allowed_actions in the unsupported-action response.');
}

return [{
  json: {
    ...body,
    action,
    received_at: now,
    document_id: '1rdPmYmhCehx_3bI737dkg8NyiutwIu3NAav7B-mbwlw',
