  }
}];

/*
CREATE NEW GUEST + INQUIRY
Expected payload from admin page:
{
  action: 'create_guest_and_inquiry',
  guest_row: {...whatsapp_guests columns...},
  inquiry_row: {...whatsapp_inquiries columns...}
}

Recommended wiring after this node:
1. Google Sheets Append to whatsapp_guests using $json.guest_row.
2. Google Sheets Append to whatsapp_inquiries using $json.inquiry_row.
3. Respond with { ok:true, record:$json.inquiry_row }.
*/
const guest = $json.guest_row || {};
const inquiry = $json.inquiry_row || $json.record || {};
if (!guest.guest_id) throw new Error('Missing guest_row.guest_id');
if (!inquiry.inquiry_id) throw new Error('Missing inquiry_row.inquiry_id');
return [{ json: { ok: true, action: $json.action, guest_row: guest, inquiry_row: inquiry, record: inquiry } }];

