{
  action: 'create_returning_inquiry',
  inquiry_row: {...whatsapp_inquiries columns...}
}

Recommended wiring after this node:
1. Google Sheets Append to whatsapp_inquiries using $json.inquiry_row.
2. Optional: update whatsapp_guests total_inquiries / last_contact_date.
3. Respond with { ok:true, record:$json.inquiry_row }.
*/
const inquiry = $json.inquiry_row || $json.record || {};
if (!inquiry.guest_id) throw new Error('Missing inquiry_row.guest_id');
if (!inquiry.inquiry_id) throw new Error('Missing inquiry_row.inquiry_id');
return [{ json: { ok: true, action: $json.action, inquiry_row: inquiry, record: inquiry } }];

const request = $('Normalize Request').first().json;
const incoming = { ...(request.inquiry_row || request.record || {}) };
const clean = value => String(value ?? '').trim();
const key = value => clean(value).toLowerCase().replace(/[-\s]+/g, '_');
const yes = value => ['yes', 'true', '1', 'y'].includes(key(value));
const terminal = new Set(['completed', 'cancelled', 'canceled', 'did_not_book', 'duplicate', 'archived']);

if (!clean(incoming.inquiry_id)) {
  throw new Error('Missing inquiry_id for update.');
}

const rows = $input.all().map(item => item.json || item);
const existing = rows.find(row => clean(row.inquiry_id) === clean(incoming.inquiry_id));

if (!existing) {
  throw new Error('Inquiry not found in crm_inquiries: ' + incoming.inquiry_id);
}

const record = { ...existing, ...incoming };
const protectedFields = [
  'country',
  'home_country',
  'tour_type',
  'tour_category',
  'interest_category',
  'service_type',
  'product_selected',
  'duration_preference',
  'tour_items',
