  'guest_calendar_synced_at',
  'inquiry_studio_id',
  'inquiry_studio_status',
  'inquiry_studio_updated_at'
];

for (const field of protectedFields) {
  if (!clean(incoming[field]) && clean(existing[field])) {
    record[field] = existing[field];
  }
}

const explicitArchiveRestore = yes(existing.is_archived)
  && !yes(incoming.is_archived)
  && !clean(incoming.archived_at)
  && !clean(incoming.archive_reason)
  && /restored from duplicate archive/i.test(clean(incoming.internal_notes));
const explicitLifecycleOverride = yes(incoming.lifecycle_override) || explicitArchiveRestore;
const existingStatus = key(existing.status);
const incomingStatus = key(incoming.status);

if (!explicitLifecycleOverride && yes(existing.is_archived)) {
  record.status = existing.status || 'duplicate';
  record.is_archived = existing.is_archived || 'Yes';
  record.archived_at = existing.archived_at || record.archived_at;
  record.archive_reason = existing.archive_reason || record.archive_reason || 'archived';
  record.superseded_by_inquiry_id = existing.superseded_by_inquiry_id || record.superseded_by_inquiry_id;
  record.priority = '';
} else if (!explicitLifecycleOverride && terminal.has(existingStatus) && !terminal.has(incomingStatus)) {
  record.status = existing.status;
  record.completed_date = existing.completed_date || record.completed_date;
  record.tour_completed = existing.tour_completed || record.tour_completed;
  record.is_archived = existing.is_archived || record.is_archived;
  record.archived_at = existing.archived_at || record.archived_at;
  record.archive_reason = existing.archive_reason || record.archive_reason;
  record.superseded_by_inquiry_id = existing.superseded_by_inquiry_id || record.superseded_by_inquiry_id;
  record.priority = '';
}

delete record.lifecycle_override;
record.country = clean(record.country) || clean(record.home_country);
record.home_country = clean(record.home_country) || clean(record.country);
record.tour_type = clean(record.tour_type) || clean(record.tour_category) || clean(record.interest_category);
record.tour_category = clean(record.tour_category) || clean(record.tour_type);
record.interest_category = clean(record.interest_category) || clean(record.tour_type);
record.updated_at = new Date().toISOString();

return [{ json: { ok: true, action: 'update_inquiry', record, inquiry_row: record } }];

