const action = String(request.action || '');
const now = new Date().toISOString();
const clean = value => String(value ?? '').trim();
const yes = value => ['yes','true','1','y'].includes(clean(value).toLowerCase());
const rows = $input.all().map(item => item.json || item).filter(row => row && Object.keys(row).length && Object.values(row).some(value => clean(value) !== ''));
const user = value => { const v=clean(value).toUpperCase(); if(!['SS','JPG'].includes(v)) throw new Error('created_by/provider_informed_by must be SS or JPG.'); return v; };
const makeId = prefix => prefix + '-' + now.replace(/[-:.TZ]/g,'').slice(0,14) + '-' + Math.random().toString(36).slice(2,8).toUpperCase();

const allowedDirections=['incoming','outgoing','internal'];
