  const records=active.filter(r=>(!guest||clean(r.guest_id)===guest)&&(!inquiry||clean(r.inquiry_id)===inquiry)).sort((a,b)=>clean(b.occurred_at||b.created_at).localeCompare(clean(a.occurred_at||a.created_at)));
  return [{json:{ok:true,action,count:records.length,records,_route:'respond'}}];
}
let incoming={...(request.interaction||request.record||{})};
let existing={};
if(action!=='create_interaction'){
  const key=clean(incoming.interaction_id||request.interaction_id); existing=rows.find(r=>clean(r.interaction_id)===key)||{}; if(!key||!existing.interaction_id) throw new Error('Interaction not found.');
}
let record={...existing,...incoming};
if(action==='create_interaction') record.interaction_id=record.interaction_id||makeId('INT');
if(!clean(record.guest_id)&&!clean(record.inquiry_id)) throw new Error('Interaction requires guest_id or inquiry_id.');
if(!clean(record.note)) throw new Error('Interaction note is required.');
record.direction=clean(record.direction||'internal').toLowerCase(); if(!allowedDirections.includes(record.direction)) throw new Error('Invalid interaction direction.');
record.channel=clean(record.channel||'other').toLowerCase(); if(!allowedChannels.includes(record.channel)) throw new Error('Invalid interaction channel.');
record.interaction_type=clean(record.interaction_type||'other').toLowerCase(); if(!allowedTypes.includes(record.interaction_type)) throw new Error('Invalid interaction_type.');
record.created_by=user(record.created_by||request.created_by);
record.followup_required=yes(record.followup_required)?'Yes':'No';
record.occurred_at=clean(record.occurred_at)||now; record.created_at=clean(existing.created_at||record.created_at)||now; record.updated_at=now;
