const rows = $input.all()
  .map(item => item.json || item)
  .filter(row => row && Object.keys(row).length && Object.values(row).some(value => clean(value) !== ''));
const user = value => {
  const v = clean(value).toUpperCase();
  if (!['SS','JPG'].includes(v)) throw new Error('created_by/provider_informed_by must be SS or JPG.');
  return v;
};
const makeId = prefix => prefix + '-' + now.replace(/[-:.TZ]/g,'').slice(0,14) + '-' + Math.random().toString(36).slice(2,8).toUpperCase();

const allowedStatus = ['pending','confirmed','cancelled','completed'];
const active = rows.filter(r => !yes(r.is_deleted));

if (action === 'list_assignments') {
  const guest = clean(request.guest_id);
  const inquiry = clean(request.inquiry_id);
  const from = clean(request.date_from);
  const to = clean(request.date_to);
  const service = clean(request.service_type).toLowerCase();

  const records = active
    .filter(r =>
      (!guest || clean(r.guest_id) === guest) &&
      (!inquiry || clean(r.inquiry_id) === inquiry) &&
      (!from || clean(r.service_date) >= from) &&
      (!to || clean(r.service_date) <= to) &&
      (!service || clean(r.service_type).toLowerCase() === service)
    )
    .sort((a,b) => (clean(a.service_date) + ' ' + clean(a.start_time))
      .localeCompare(clean(b.service_date) + ' ' + clean(b.start_time)));

  return [{ json: { ok: true, action, count: records.length, records, _route: 'respond' } }];
}

if (action === 'invite_assignment_provider') {
  const key = clean(request.assignment_id || request.assignment?.assignment_id || request.record?.assignment_id);
  const existing = rows.find(r => clean(r.assignment_id) === key) || {};
  if (!key || !existing.assignment_id) throw new Error('Assignment not found.');
  if (yes(existing.is_deleted)) throw new Error('Cannot invite a provider for a deleted assignment.');
  if (['cancelled','completed'].includes(clean(existing.assignment_status).toLowerCase())) throw new Error('Cannot invite a provider for a closed assignment.');
  if (!clean(existing.google_calendar_event_id)) throw new Error('This assignment has not synced to Google Calendar yet.');
  return [{ json: { ...existing, _action: action, _route: 'invite' } }];
}

let incoming = { ...(request.assignment || request.record || {}) };
let existing = {};

if (action !== 'create_assignment') {
  const key = clean(incoming.assignment_id || request.assignment_id);
  existing = rows.find(r => clean(r.assignment_id) === key) || {};
  if (!key || !existing.assignment_id) throw new Error('Assignment not found.');
