let record = { ...existing, ...incoming };

if (action === 'create_assignment') {
  record.assignment_id = record.assignment_id || makeId('ASN');
  record.assignment_group_id = record.assignment_group_id || makeId('ASG');
}

if (!clean(record.guest_id) && !clean(record.inquiry_id)) {
  throw new Error('Assignment requires guest_id or inquiry_id.');
}
if (!clean(record.service_date)) throw new Error('service_date is required.');
if (!clean(record.service_type)) throw new Error('service_type is required.');

record.assignment_status = clean(record.assignment_status || 'pending').toLowerCase();
if (!allowedStatus.includes(record.assignment_status)) throw new Error('Invalid assignment_status.');

record.provider_informed = yes(record.provider_informed) ? 'Yes' : 'No';
if (record.provider_informed === 'Yes') {
  record.provider_informed_at = clean(record.provider_informed_at) || now;
  record.provider_informed_by = user(record.provider_informed_by || request.created_by);
} else {
  record.provider_informed_at = '';
  record.provider_informed_by = '';
}

record.round_trip = yes(record.round_trip) ? 'Yes' : 'No';
record.currency = clean(record.currency || 'USD').toUpperCase();
record.created_by = user(record.created_by || request.created_by);
record.created_at = clean(existing.created_at || record.created_at) || now;
record.updated_at = now;

// Preserve all calendar identity fields across normal CRM edits.
// The calendar arm below is responsible for changing these values after Google succeeds.
record.google_calendar_event_id = clean(existing.google_calendar_event_id || record.google_calendar_event_id);
record.google_calendar_id = clean(existing.google_calendar_id || record.google_calendar_id) || 'mindobirdwatching@gmail.com';
record.calendar_event_url = clean(existing.calendar_event_url || record.calendar_event_url);
record.calendar_synced_at = clean(existing.calendar_synced_at || record.calendar_synced_at);
record.calendar_sync_error = '';

if (action === 'delete_assignment') {
  record.is_deleted = 'Yes';
  record.deleted_at = now;
  record.calendar_sync_status = record.google_calendar_event_id ? 'pending_delete' : 'not_required';
} else {
  record.is_deleted = 'No';
  record.deleted_at = '';
  if (record.assignment_status === 'cancelled') {
    record.calendar_sync_status = record.google_calendar_event_id ? 'pending_delete' : 'not_required';
  } else {
    record.calendar_sync_status = record.google_calendar_event_id ? 'pending_update' : 'pending_create';
  }
}

return [{ json: { ...record, _action: action, _route: 'write' } }];

const original = $('Process CRM Assignments').item.json;
const latest = $json || {};
const merged = { ...original, ...latest };
