const rows = $input.all().map(item => item.json || item).filter(row => row && Object.keys(row).length && Object.values(row).some(value => clean(value) !== ''));
const user = value => { const v=clean(value).toUpperCase(); if(!['SS','JPG'].includes(v)) throw new Error('created_by/provider_informed_by must be SS or JPG.'); return v; };
const makeId = prefix => prefix + '-' + now.replace(/[-:.TZ]/g,'').slice(0,14) + '-' + Math.random().toString(36).slice(2,8).toUpperCase();

const service=clean(request.service_type).toLowerCase();
const records=rows.filter(r=>!service||clean(r.service_type).toLowerCase()===service).filter(r=>!clean(r.is_active)||yes(r.is_active)).sort((a,b)=>{const d=(yes(b.is_default)?1:0)-(yes(a.is_default)?1:0);return d||clean(a.provider_name).localeCompare(clean(b.provider_name));});
return [{json:{ok:true,action:'list_providers',count:records.length,records,_route:'respond'}}];

const request = $('Normalize Request').first().json;
const record = $('Process CRM Assignments').item.json;
const clean = value => String(value ?? '').trim();
const html = value => clean(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');
const yes = value => ['yes','true','1','y'].includes(clean(value).toLowerCase());

function normalizeTime(value) {
  const raw = clean(value).toLowerCase();
  if (!raw) return '';
  const m = raw.match(/^(\d{1,2}):(\d{2})(?:\s*(am|pm))?/);
  if (!m) return '';
  let h = Number(m[1]);
  const min = Number(m[2]);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  if (h > 23 || min > 59) return '';
  return String(h).padStart(2,'0') + ':' + String(min).padStart(2,'0');
}

function addMinutesLocal(date, time, minutes) {
  const [y,m,d] = date.split('-').map(Number);
  const [hh,mm] = time.split(':').map(Number);
  const dt = new Date(Date.UTC(y,m-1,d,hh,mm,0));
  dt.setUTCMinutes(dt.getUTCMinutes() + minutes);
  const yyyy = dt.getUTCFullYear();
  const mo = String(dt.getUTCMonth()+1).padStart(2,'0');
  const da = String(dt.getUTCDate()).padStart(2,'0');
  const h = String(dt.getUTCHours()).padStart(2,'0');
  const mi = String(dt.getUTCMinutes()).padStart(2,'0');
  return { date: `${yyyy}-${mo}-${da}`, time: `${h}:${mi}` };
}

const date = clean(record.service_date);
const startTime = normalizeTime(record.start_time);
const endTimeRaw = normalizeTime(record.end_time);
const calendarId = clean(record.google_calendar_id) || 'mindobirdwatching@gmail.com';
const existingEventId = clean(record.google_calendar_event_id);
const providerNameForColor = (clean(record.provider_name) === 'Other' ? clean(record.provider_name_other) : clean(record.provider_name)).toLowerCase();
const calendarColorId = providerNameForColor === 'chicho' ? '10'
  : providerNameForColor === 'juan' ? '9'
  : providerNameForColor === 'neicer' ? '5'
  : '';
const cancelled = yes(record.is_deleted) || clean(record.assignment_status).toLowerCase() === 'cancelled';

let calendarAction = 'skip';
let skipReason = '';

if (cancelled) {
  calendarAction = existingEventId ? 'delete' : 'skip';
  if (!existingEventId) skipReason = 'No Google Calendar event exists to delete.';
} else if (!date || !startTime) {
  calendarAction = 'skip';
  skipReason = !date ? 'Service date is missing.' : 'Start time is missing.';
} else {
  calendarAction = existingEventId ? 'update' : 'create';
}

let endDate = date;
let endTime = endTimeRaw;
let endWasDefaulted = false;

if (!cancelled && date && startTime && !endTime) {
  const fallback = addMinutesLocal(date, startTime, 60);
  endDate = fallback.date;
  endTime = fallback.time;
  endWasDefaulted = true;
} else if (!cancelled && date && startTime && endTime && endTime <= startTime) {
  const overnight = addMinutesLocal(date, endTime, 24 * 60);
  endDate = overnight.date;
}

const titleParts = [
